import'./cloud-sync.js';import{LOGIC_TRACKS,LOGIC_CHAIN,LOGIC_DIAGNOSTIC,recommendLogicTrack,logicChoiceIndex,freshLogicChoiceIndex,createBlankLogicLearner}from'./logic-data.js?v=logic1';
const $=s=>document.querySelector(s),key='mathlab-logic-v1',memory={};function blankStore(){return{a:createBlankLogicLearner(),b:createBlankLogicLearner(),learner:'a'}}function read(){try{return JSON.parse(localStorage.getItem(key))||blankStore()}catch{return memory.data||blankStore()}}let store=read(),learner=store.learner||'a',state=store[learner]||createBlankLogicLearner(),errors=0,hints=0,work={},sessionId=null;
function ensure(){const b=createBlankLogicLearner();state={...b,...state,diagnostic:{...b.diagnostic,...state.diagnostic},missions:{...state.missions},sessions:{...state.sessions},evidence:{...b.evidence,...state.evidence},family:{...b.family,...state.family}}}function save(){state.updatedAt=new Date().toISOString();store={...read(),[learner]:state,learner};memory.data=store;try{localStorage.setItem(key,JSON.stringify(store));$('#saveStatus').textContent='Saved offline · cloud sync follows parent sign-in'}catch{$('#saveStatus').textContent='Progress lasts until this page closes.'}}function saveLearner(){store={...read(),learner};memory.data=store;try{localStorage.setItem(key,JSON.stringify(store))}catch{}}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function feedback(s,t=''){const e=$('#feedback');e.textContent=s;e.className='feedback '+t}function track(){return LOGIC_TRACKS[state.track||'explorer']}function done(i){return Boolean(state.missions[LOGIC_CHAIN.missions[i].id]?.complete)}function unlocked(i){return i===0||done(i-1)}function loadSession(id){sessionId=id;const s=state.sessions[id]||{errors:0,hints:0,work:{}};errors=s.errors||0;hints=s.hints||0;work=s.work||{}}function saveSession(){if(sessionId){state.sessions[sessionId]={errors,hints,work};save()}}function miss(s){errors++;saveSession();feedback(s,'try')}function mark(d,ind){if(ind)state.evidence[d]='independent';else if(state.evidence[d]==='unknown')state.evidence[d]='learning'}
function complete(i,dims,pending=false,preview=false){const m=LOGIC_CHAIN.missions[i],sid=sessionId;state.missions[m.id]={complete:!preview,preview,errors,hints,completedAt:new Date().toISOString(),track:state.track};dims.forEach(d=>mark(d,errors===0&&hints===0&&!preview));if(pending){state.retestDue=Date.now()+20*60*60*1000;state.evidence.transfer=state.evidence.transfer==='unknown'?'learning':state.evidence.transfer}if(preview)state.previewFresh=false;if(!preview&&i<4)state.activeMission=i+1;if(sid)delete state.sessions[sid];errors=0;hints=0;work={};sessionId=null;save();setTimeout(render,420)}function hint(s){return hints?`<div class="hint-box">${esc(s)}</div>`:''}function controls(){return'<div class="answer-row"><button class="secondary" data-action="hint">Give me one hint</button></div>'}
function ordered(correct,decoys,seed,forced=null){const items=[correct,...decoys],shift=forced==null?logicChoiceIndex(seed,items.length):(0-forced+items.length)%items.length,tagged=items.map((text,i)=>({text,correct:i===0}));return tagged.slice(shift).concat(tagged.slice(0,shift))}function choices(correct,decoys,attr,seed,forced=null){return`<div class="answer-grid">${ordered(correct,decoys,seed,forced).map(x=>`<button class="choice" data-${attr}="${x.correct?'correct':'wrong'}">${esc(x.text)}</button>`).join('')}</div>`}function facts(q){return q.facts.length?`<div class="logic-facts"><strong>FACTS AND RULES</strong>${q.facts.map((x,i)=>`<p><b>${i+1}</b>${esc(x)}</p>`).join('')}</div>`:''}function proofDecoys(q){return['It looks close, so one failed condition can be ignored.','The rule can be reversed even when the facts do not say so.'].filter(x=>x!==q.why)}
function renderDiagnostic(){const d=state.diagnostic;if(d.index>=LOGIC_DIAGNOSTIC.length){state.track=state.track||recommendLogicTrack(d.score);const t=track();$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">STARTING DEPTH FOUND</p><h3>${t.label}</h3><p>${t.description}</p><p class="microcopy">This selects useful logic practice. It is not a grade or test score.</p><button class="primary" data-action="start">Start the logic cases →</button></div>`;return}const q=LOGIC_DIAGNOSTIC[d.index];if(d.phase==='why'){$('#activity').innerHTML=`<div class="diagnostic-progress"><span style="width:${d.index/3*100}%"></span></div><p class="eyebrow">EXPLAIN QUESTION ${d.index+1}</p><h3>Why does that conclusion follow?</h3>${choices(q.why,['One important word can be ignored.','The condition works in either direction.'],'diagnostic-why',q.prompt+':why')}<p class="microcopy">Choosing an answer and explaining it are separate skills.</p>`;document.querySelectorAll('[data-diagnostic-why]').forEach(b=>b.onclick=()=>{const reasonCorrect=b.dataset.diagnosticWhy==='correct',overall=Boolean(d.choiceCorrect&&reasonCorrect);d.answers.push({index:d.index,choiceCorrect:Boolean(d.choiceCorrect),reasonCorrect});if(overall)d.score++;d.index++;delete d.phase;delete d.choiceCorrect;feedback(overall?'The answer and reason agree.':q.why,overall?'good':'try');save();setTimeout(()=>{feedback('');render()},450)});return}$('#activity').innerHTML=`<div class="diagnostic-progress"><span style="width:${d.index/3*100}%"></span></div><p class="eyebrow">QUESTION ${d.index+1} OF 3</p><h3>${esc(q.prompt)}</h3>${choices(q.correct,q.decoys,'diagnostic',q.prompt)}<p class="microcopy">No timer. First choose; then explain why.</p>`;document.querySelectorAll('[data-diagnostic]').forEach(b=>b.onclick=()=>{d.choiceCorrect=b.dataset.diagnostic==='correct';d.phase='why';feedback(d.choiceCorrect?'Now explain why.':'Now check the reason before moving on.',d.choiceCorrect?'good':'try');save();setTimeout(render,350)})}
function renderCase(q,i,dim,label,forced=null,preview=false){if(!work.answer){$('#activity').innerHTML=`<p class="eyebrow">${label}</p><h3>${esc(q.prompt)}</h3>${facts(q)}${choices(q.correct,q.decoys,'case',`${track().id}:${i}:answer`,forced)}${controls()}${hint(i===1?'Compare words like all, some, none, exactly, and not. Do not make the claim stronger than the facts.':i===2?'Start with the stated IF. Move only in the arrow’s direction.':i===3?'Check each condition separately. One failure eliminates a choice.':'Check every changed condition; do not rely on answer position.')}`;document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{if(b.dataset.case==='correct'){work={answer:true};saveSession();feedback('The choice fits. Now prove it from the words.','good');setTimeout(renderMission,350)}else miss('That choice changes, reverses, or ignores at least one condition.')});return}$('#activity').innerHTML=`<p class="eyebrow">EXPLAIN THE LOGIC</p><h3>Why is that conclusion justified?</h3>${facts(q)}${choices(q.why,proofDecoys(q),'proof',`${track().id}:${i}:proof`,forced==null?null:(forced+1)%3)}${controls()}${hint('A complete explanation names the condition and shows exactly how the chosen answer satisfies it.')}`;document.querySelectorAll('[data-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.proof==='correct'){feedback(preview?'Preview complete. Return later for fresh evidence.':'The conclusion and explanation agree.','good');complete(i,[dim],i===3,preview)}else miss('That explanation ignores evidence or uses the rule backward.')})}
function renderFresh(){const due=state.retestDue||Date.now()+20*60*60*1000,ready=Date.now()>=due;if(!ready&&!state.previewFresh){const hours=Math.max(1,Math.ceil((due-Date.now())/3600000));$('#activity').innerHTML=`<div class="lock-card"><p class="eyebrow">FRESH CHECK</p><strong>Return after the logic steps have faded from memory.</strong><p>About ${hours} hours remain. Waiting checks whether the learner can rebuild the reasoning.</p><button class="secondary" data-action="preview">Preview for family review</button><p class="microcopy">Preview uses a different case and cannot count as delayed evidence.</p></div>`;return}const q=ready?track().fresh.challenge:track().fresh.preview,forced=freshLogicChoiceIndex(track().id,'case',ready,3);renderCase(q,4,'transfer',ready?'DELAYED CHECK · CHANGED CASE':'FAMILY PREVIEW · CHANGED CASE',forced,!ready)}
function renderComplete(i){$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">MISSION COMPLETE</p><h3>${esc(LOGIC_CHAIN.missions[i].title)}</h3><p>${i===3?'A changed challenge unlocks after a delay.':'The reasoning is saved for this learner.'}</p></div>`}function renderMission(){const i=state.activeMission,m=LOGIC_CHAIN.missions[i],ready=i===4&&Boolean(state.retestDue)&&Date.now()>=state.retestDue,sid=i===4?`${m.id}:${ready?'challenge':'preview'}`:m.id;if(sessionId!==sid)loadSession(sid);$('#missionEyebrow').textContent=`MISSION ${m.number} · ${m.kind.replace('-',' ').toUpperCase()}`;$('#missionTitle').textContent=m.title;$('#missionObjective').textContent=m.objective;$('#missionTime').textContent=`ABOUT ${m.minutes} MIN`;feedback('');if(done(i)){renderComplete(i);return}if(i===0)renderDiagnostic();else if(i===1)renderCase(track().language,1,'language','PRECISE LANGUAGE');else if(i===2)renderCase(track().inference,2,'inference','IF–THEN DIRECTION');else if(i===3)renderCase(track().eliminate,3,'elimination','ELIMINATE WITH EVIDENCE');else renderFresh()}
function renderNav(){$('#missionNav').innerHTML=LOGIC_CHAIN.missions.map((m,i)=>`<button class="mission-button ${state.activeMission===i?'active':''} ${done(i)?'done':''}" data-mission="${i}" ${unlocked(i)?'':'disabled'}><span class="mission-number">${m.number}</span><span class="mission-label">${esc(m.title)}</span><span class="mission-state">${done(i)?'✓':unlocked(i)?'›':'◌'}</span></button>`).join('');document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{state.activeMission=Number(b.dataset.mission);sessionId=null;save();render()})}function renderTrack(){const t=track();$('#trackCard').innerHTML=`<strong>Current depth: ${t.label}</strong><span>${t.description}</span><select id="trackSelect" aria-label="Learning depth">${Object.values(LOGIC_TRACKS).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.label}</option>`).join('')}</select><small>Changing depth restarts this review path so evidence is not mixed.</small>`;$('#trackSelect').onchange=e=>{state={...createBlankLogicLearner(),track:e.target.value,family:state.family};sessionId=null;save();render()}}function renderEvidence(){const name=learner==='a'?'Ella':'Mila',labels={language:'Precise evidence language',inference:'Follow if–then forward',elimination:'Check every condition',transfer:'Fresh logic transfer'};$('#evidenceTitle').textContent=`${name}’s learning evidence`;$('#reviewBannerTitle').textContent=`Built for ${name} · waiting family review`;$('#evidenceGrid').innerHTML=Object.entries(labels).map(([k,v])=>`<div class="evidence-item"><header><span>${v}</span><span>${state.evidence[k]==='independent'?'Independent':state.evidence[k]==='learning'?'Learning':'Not checked'}</span></header></div>`).join('')}function renderFamily(){$('#helpNote').value=state.family.help;$('#explainNote').value=state.family.explain;$('#continueNote').value=state.family.continue}function render(){ensure();$('#learnerSelect').value=learner;renderTrack();renderNav();renderEvidence();renderFamily();renderMission()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='start'){state.missions['logic-start']={complete:true,score:state.diagnostic.score,completedAt:new Date().toISOString()};state.activeMission=1;sessionId=null;save();render()}else if(b.dataset.action==='hint'){hints++;saveSession();renderMission()}else if(b.dataset.action==='preview'){state.previewFresh=true;save();render()}});$('#learnerSelect').onchange=e=>{learner=e.target.value;state=read()[learner]||createBlankLogicLearner();sessionId=null;ensure();saveLearner();render()};for(const[id,k]of[['helpNote','help'],['explainNote','explain'],['continueNote','continue']])$('#'+id).addEventListener('input',e=>{state.family[k]=e.target.value;save()});$('#resetPath').onclick=()=>{if(confirm(`Reset the logic review path for ${learner==='a'?'Ella':'Mila'}?`)){state=createBlankLogicLearner();sessionId=null;save();render()}};if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));ensure();render();
